 "<b style=\"font-size:26px;color:#b2791f\">Triada</b><br><span style=\"font-size:21px;color:#35121d\">Tres colores equidistantes: vivos y equilibrados.</span>": "<b style=\"font-size:26px;color:#b2791f\">Triada</b><br><span style=\"font-size:21px;color:#35121d\">Hiru kolore distantzia berera: bizi eta orekatuak.</span>",
